## Tests

```javascript
import { clamp, lerp, randomInt } from "./mathUtils.js";

// ── clamp ────────────────────────────────────────────────────────────────────
console.assert(clamp(15,  0, 10) === 10,  "clamp: above max → max");
console.assert(clamp(-5,  0, 10) ===  0,  "clamp: below min → min");
console.assert(clamp( 7,  0, 10) ===  7,  "clamp: within range → unchanged");
console.assert(clamp( 0,  0, 10) ===  0,  "clamp: equal to min → min");
console.assert(clamp(10,  0, 10) === 10,  "clamp: equal to max → max");

try { clamp(5, 10, 0); console.assert(false, "clamp: should throw"); }
catch (e) { console.assert(e instanceof RangeError, "clamp: throws RangeError"); }

// ── lerp ─────────────────────────────────────────────────────────────────────
console.assert(lerp(0, 100, 0)   ===   0, "lerp: t=0 → a");
console.assert(lerp(0, 100, 1)   === 100, "lerp: t=1 → b");
console.assert(lerp(0, 100, 0.5) ===  50, "lerp: t=0.5 → midpoint");
console.assert(lerp(0, 100, 1.5) === 150, "lerp: t>1 → extrapolation");
console.assert(lerp(10,  20, 0.25) === 12.5, "lerp: fractional step");

// ── randomInt ────────────────────────────────────────────────────────────────
const TRIALS = 10_000;
const results = new Set();

for (let i = 0; i < TRIALS; i++) {
  const n = randomInt(1, 6);
  console.assert(Number.isInteger(n),  "randomInt: result is an integer");
  console.assert(n >= 1 && n <= 6,     "randomInt: result is in [1, 6]");
  results.add(n);
}

// After 10 000 trials every value in [1,6] should have appeared at least once.
console.assert(results.size === 6, "randomInt: all values in range produced");

console.assert(randomInt(5, 5) === 5, "randomInt: min === max → that value");

try { randomInt(10, 0); console.assert(false, "randomInt: should throw"); }
catch (e) { console.assert(e instanceof RangeError, "randomInt: throws RangeError"); }

console.log("All tests passed ✓");
```

