```javascript
// mathUtils.test.js  (Jest / Vitest compatible)
import { clamp, lerp, randomInt } from "./mathUtils.js";

// ── clamp ────────────────────────────────────────────────────────────────────
describe("clamp", () => {
  test("returns min when value is below range", () => {
    expect(clamp(-5, 0, 10)).toBe(0);
  });

  test("returns max when value is above range", () => {
    expect(clamp(15, 0, 10)).toBe(10);
  });

  test("returns value when it is within range", () => {
    expect(clamp(7, 0, 10)).toBe(7);
  });

  test("returns value when it equals min", () => {
    expect(clamp(0, 0, 10)).toBe(0);
  });

  test("returns value when it equals max", () => {
    expect(clamp(10, 0, 10)).toBe(10);
  });

  test("works when min equals max", () => {
    expect(clamp(5, 3, 3)).toBe(3);
  });

  test("throws RangeError when min > max", () => {
    expect(() => clamp(5, 10, 0)).toThrow(RangeError);
  });
});

// ── lerp ─────────────────────────────────────────────────────────────────────
describe("lerp", () => {
  test("returns a when t = 0", () => {
    expect(lerp(0, 100, 0)).toBe(0);
  });

  test("returns b when t = 1", () => {
    expect(lerp(0, 100, 1)).toBe(100);
  });

  test("returns midpoint when t = 0.5", () => {
    expect(lerp(0, 100, 0.5)).toBe(50);
  });

  test("allows extrapolation beyond [0, 1]", () => {
    expect(lerp(0, 100, 1.5)).toBe(150);
    expect(lerp(0, 100, -0.5)).toBe(-50);
  });

  test("works with negative ranges", () => {
    expect(lerp(-50, 50, 0.5)).toBe(0);
  });
});

// ── randomInt ────────────────────────────────────────────────────────────────
describe("randomInt", () => {
  test("always returns an integer", () => {
    for (let i = 0; i < 100; i++) {
      expect(Number.isInteger(randomInt(0, 100))).toBe(true);
    }
  });

  test("result is always within [min, max]", () => {
    for (let i = 0; i < 200; i++) {
      const result = randomInt(1, 6);
      expect(result).toBeGreaterThanOrEqual(1);
      expect(result).toBeLessThanOrEqual(6);
    }
  });

  test("returns min when min equals max", () => {
    expect(randomInt(5, 5)).toBe(5);
  });

  test("works with negative bounds", () => {
    for (let i = 0; i < 100; i++) {
      const result = randomInt(-10, -1);
      expect(result).toBeGreaterThanOrEqual(-10);
      expect(result).toBeLessThanOrEqual(-1);
    }
  });

  test("throws RangeError when min > max", () => {
    expect(() => randomInt(10, 5)).toThrow(RangeError);
  });
});
