```javascript
/**
 * Removes accent characters from a string by normalizing to NFD form
 * and stripping combining diacritical marks.
 *
 * @param {string} str - The input string.
 * @returns {string} The string with accents removed.
 *
 * @example
 * stripAccents('Héllo Wörld') // => 'Hello World'
 * stripAccents('café')        // => 'cafe'
 */
function stripAccents(str) {
  if (typeof str !== "string") {
    throw new TypeError(`Expected a string, got ${typeof str}`);
  }

  // NFD decomposes characters into base letter + combining mark(s).
  // The regex then removes every character in the "Mark, Nonspacing" Unicode
  // category (U+0300–U+036F), which covers all common diacritical marks.
  return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

/**
 * Converts a string into a URL-friendly slug.
 *
 * Steps applied in order:
 *  1. Strip accents / diacritical marks.
 *  2. Convert to lower-case.
 *  3. Replace `&` with the word "and".
 *  4. Remove characters that are not alphanumeric, spaces, or hyphens.
 *  5. Collapse whitespace and hyphens into a single hyphen.
 *  6. Trim leading / trailing hyphens.
 *
 * @param {string} str - The input string.
 * @returns {string} A lower-case, hyphen-separated slug.
 *
 * @example
 * slugify('Hello World')              // => 'hello-world'
 * slugify('  Héllo   Wörld  ')        // => 'hello-world'
 * slugify('Café & Crêpes')            // => 'cafe-and-crepes'
 * slugify('This is a test!!!')        // => 'this-is-a-test'
 * slugify('  --Leading hyphens-- ')   // => 'leading-hyphens'
 */
function slugify(str) {
  if (typeof str !== "string") {
    throw new TypeError(`Expected a string, got ${typeof str}`);
  }

  return (
    stripAccents(str)
      // Lower-case everything
      .toLowerCase()
      // Replace ampersands with "and"
      .replace(/&/g, " and ")
      // Remove anything that is not a letter, digit, space, or hyphen
      .replace(/[^a-z0-9\s-]/g, "")
      // Collapse consecutive whitespace / hyphens into a single hyphen
      .replace(/[\s-]+/g, "-")
      // Remove leading and trailing hyphens
      .replace(/^-+|-+$/g, "")
  );
}

module.exports = { slugify, stripAccents };
```

