 *  7. Strip leading / trailing hyphens.
 *
 * @param {string} str - The input string.
 * @returns {string} A slug suitable for use in URLs.
 *
 * @example
 * slugify('Hello World');              // → 'hello-world'
 * slugify('  Héllo   Wörld  ');        // → 'hello-world'
 * slugify('Crème brûlée & Soufflé');  // → 'creme-brulee-and-souffle'
 * slugify('100% Organic!');            // → '100-organic'
 * slugify('already-a-slug');           // → 'already-a-slug'
 */
function slugify(str) {
  if (typeof str !== 'string') {
    throw new TypeError(`slugify expects a string, got ${typeof str}`);
  }

  return (
    str
      // 1. Trim surrounding whitespace.
      .trim()

      // 2. Strip diacritical marks.
      // Uses the helper defined above so the logic lives in one place.
      .replace(/./gsu, (char) => stripAccents(char))

      // 3. Lower-case everything.
      .toLowerCase()

      // 4. Replace '&' with 'and' so "&" isn't silently dropped.
      .replace(/&/g, ' and ')

      // 5. Remove characters that are not alphanumeric, spaces, or hyphens.
      .replace(/[^a-z0-9\s-]/g, '')

      // 6. Collapse one-or-more whitespace characters / hyphens into a
      //    single hyphen so "hello   world" → "hello-world".
      .replace(/[\s-]+/g, '-')

      // 7. Remove any leading or trailing hyphens that may have been
      //    introduced by the previous steps.
      .replace(/^-+|-+$/g, '')
  );
}

module.exports = { slugify, stripAccents };
```

