formatDate(new Date("2024-02-29T23:59:59.999Z")); // leap year
// → "2024-02-29T23:59:59.999Z"

// ── parseDate — calendar ──────────────────────────────────────────────────────

parseDate("2024-03-15");
// → 2024-03-15T00:00:00.000Z

parseDate("2024-03-15T14:30");
// → 2024-03-15T14:30:00.000Z

parseDate("2024-03-15T14:30:00.500Z");
// → 2024-03-15T14:30:00.500Z

parseDate("2024-03-15T14:30:00+05:30");
// → 2024-03-15T09:00:00.000Z  (converted to UTC)

parseDate("2024-03-15T14:30:00-07:00");
// → 2024-03-15T21:30:00.000Z

// ── parseDate — week date ─────────────────────────────────────────────────────

parseDate("2024-W11-5");  // Friday of week 11, 2024
// → 2024-03-15T00:00:00.000Z

// ── parseDate — ordinal date ──────────────────────────────────────────────────

parseDate("2024-075");    // 75th day of 2024
// → 2024-03-15T00:00:00.000Z

// ── round-trip ────────────────────────────────────────────────────────────────

const d = parseDate("2024-03-15T09:00:00.000Z");
formatDate(d);
// → "2024-03-15T09:00:00.000Z"

// ── errors ────────────────────────────────────────────────────────────────────

parseDate("not-a-date");  // RangeError: "not-a-date" is not a recognised ISO-8601 date string
parseDate("2024-13-01");  // RangeError: Month must be 1–12, got 13
parseDate("2023-02-29");  // RangeError: Day 29 is out of range for 2023-02
formatDate("2024-01-01"); // TypeError: Expected a Date or numeric timestamp, got string
