  if (offset !== null && !dateOnly) {
    const offsetMinutes = parseOffsetToMinutes(offset);
    workingMs += offsetMinutes * 60_000;
  }

  // Build a UTC-based representation of the (possibly shifted) time
  const tmp = new Date(workingMs);

  const year  = tmp.getUTCFullYear();
  const month = PAD(tmp.getUTCMonth() + 1);
  const day   = PAD(tmp.getUTCDate());

  if (dateOnly) {
    return `${year}-${month}-${day}`;
  }

  const hours   = PAD(tmp.getUTCHours());
  const minutes = PAD(tmp.getUTCMinutes());
  const seconds = PAD(tmp.getUTCSeconds());
  const millis  = ms ? `.${PAD(tmp.getUTCMilliseconds(), 3)}` : "";
  const suffix  = offset !== null ? normalizeOffset(offset) : "Z";

  return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}${millis}${suffix}`;
}

// ─── parseDate ────────────────────────────────────────────────────────────────

/**
 * Parses an ISO-8601 string into a Date object.
 *
 * @param {string} str - ISO-8601 date string.
 * @returns {Date} Parsed Date (always represents the same instant in UTC).
 *
 * @throws {TypeError}  if `str` is not a string.
 * @throws {SyntaxError} if `str` does not match ISO-8601.
 * @throws {RangeError}  if the parsed date is invalid (e.g. month 13).
 *
 * @example
 * parseDate("2024-03-15");
 * // → Date { 2024-03-15T00:00:00.000Z }
 *
 * parseDate("2024-03-15T10:30:00.000Z");
 * // → Date { 2024-03-15T10:30:00.000Z }
 *
 * parseDate("2024-03-15T16:00:00+05:30");
 * // → Date { 2024-03-15T10:30:00.000Z }
 */
function parseDate(str) {
  if (typeof str !== "string") {
    throw new TypeError(`parseDate: expected a string, got ${typeof str}`);
  }

  const trimmed = str.trim();
  const match = trimmed.match(ISO_DATE_REGEX);

  if (!match) {
    throw new SyntaxError(`parseDate: "${trimmed}" is not a valid ISO-8601 string`);
  }

  const [, yearStr, monthStr, dayStr, hStr, mStr, sStr, msStr, offSignH, offSignM] = match;

  const year   = parseInt(yearStr,  10);
  const month  = parseInt(monthStr, 10);
  const day    = parseInt(dayStr,   10);
  const hour   = parseInt(hStr   ?? "0",  10);
  const minute = parseInt(mStr   ?? "0",  10);
  const second = parseInt(sStr   ?? "0",  10);
  const millis = msStr ? parseInt(msStr.padEnd(3, "0"), 10) : 0;

  // Validate ranges
  validateDateParts({ year, month, day, hour, minute, second, millis });

  // Build UTC timestamp
  let utcMs = Date.UTC(year, month - 1, day, hour, minute, second, millis);

  // Subtract offset so the result is always UTC
  if (offSignH !== undefined && offSignM !== undefined) {
    const offsetMinutes = parseOffsetToMinutes(`${offSignH}:${offSignM}`);
    utcMs -= offsetMinutes * 60_000;
  }

  const result = new Date(utcMs);

  if (isNaN(result.getTime())) {
    throw new RangeError(`parseDate: "${trimmed}" produced an invalid date`);
  }

  return result;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Converts an offset string like "+05:30" or "-08:00" to total minutes.
 * @param {string} offset
 * @returns {number} Signed minutes
 */
function parseOffsetToMinutes(offset) {
  const match = offset.match(/^([+-])(\d{2}):(\d{2})$/);
  if (!match) {
    throw new SyntaxError(`Invalid UTC offset: "${offset}"`);
  }
  const sign    = match[1] === "+" ? 1 : -1;
  const hours   = parseInt(match[2], 10);
  const minutes = parseInt(match[3], 10);

  if (hours > 23 || minutes > 59) {
    throw new RangeError(`UTC offset out of range: "${offset}"`);
  }

  return sign * (hours * 60 + minutes);
}

/**
 * Normalises an offset string to "+HH:MM" / "-HH:MM".
 * @param {string} offset
 * @returns {string}
 */
function normalizeOffset(offset) {
  const match = offset.match(/^([+-])(\d{1,2}):(\d{2})$/);
  if (!match) throw new SyntaxError(`Invalid UTC offset: "${offset}"`);
  return `${match[1]}${PAD(match[2])}:${PAD(match[3])}`;
}

/**
 * Throws RangeError if any date part is out of its valid range.
 */
function validateDateParts({ year, month, day, hour, minute, second, millis }) {
  if (month  < 1  || month  > 12) throw new RangeError(`Month out of range: ${month}`);
  if (hour   < 0  || hour   > 23) throw new RangeError(`Hour out of range: ${hour}`);
  if (minute < 0  || minute > 59) throw new RangeError(`Minute out of range: ${minute}`);
  if (second < 0  || second > 59) throw new RangeError(`Second out of range: ${second}`);
  if (millis < 0  || millis > 999) throw new RangeError(`Milliseconds out of range: ${millis}`);

  // Validate day against actual days in that month (respects leap years)
  const maxDay = new Date(year, month, 0).getDate(); // day 0 of next month = last day of this month
  if (day < 1 || day > maxDay) {
    throw new RangeError(`Day ${day} is out of range for ${year}-${PAD(month)}`);
  }
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { formatDate, parseDate };
