// ─── parseDate ────────────────────────────────────────────────────────────────

/**
 * Parses an ISO-8601 string into a Date object (always UTC-normalised).
 *
 * Accepted formats
 *   YYYY-MM-DD
 *   YYYY-MM-DDTHH:mm:ss
 *   YYYY-MM-DDTHH:mm:ss.sss
 *   YYYY-MM-DDTHH:mm:ssZ
 *   YYYY-MM-DDTHH:mm:ss.sssZ
 *   YYYY-MM-DDTHH:mm:ss±HH:MM
 *   YYYY-MM-DDTHH:mm:ss.sss±HH:MM
 *
 * @param {string} str - ISO-8601 date string.
 * @returns {Date} Corresponding Date object (UTC).
 *
 * @throws {TypeError}  if `str` is not a string.
 * @throws {RangeError} if `str` does not match ISO-8601 or contains
 *                      out-of-range field values.
 *
 * @example
 * parseDate("2024-03-15");
 * // → Date { 2024-03-15T00:00:00.000Z }
 *
 * parseDate("2024-03-15T09:05:03.007-05:00");
 * // → Date { 2024-03-15T14:05:03.007Z }
 */
function parseDate(str) {
  if (typeof str !== "string") {
    throw new TypeError(`parseDate: expected a string, got ${typeof str}`);
  }

  const trimmed = str.trim();
  const match   = ISO_DATE_RE.exec(trimmed);

  if (!match) {
    throw new RangeError(
      `parseDate: "${trimmed}" is not a recognised ISO-8601 date string`
    );
  }

  const [, rawYear, rawMonth, rawDay,
          rawHour, rawMin, rawSec,
          rawMs,
          rawOffH, rawOffM] = match;

  const year  = parseInt(rawYear,  10);
  const month = parseInt(rawMonth, 10);
  const day   = parseInt(rawDay,   10);

  // Validate calendar fields
  validateField("month",  month,  1, 12);
  validateField("day",    day,    1, daysInMonth(year, month));

  // Date-only path → midnight UTC
  if (rawHour === undefined) {
    return new Date(Date.UTC(year, month - 1, day));
  }

  const hour = parseInt(rawHour, 10);
  const min  = parseInt(rawMin,  10);
  const sec  = parseInt(rawSec,  10);

  // Pad / truncate milliseconds to exactly 3 digits
  const ms = rawMs !== undefined
    ? parseInt(rawMs.padEnd(3, "0").slice(0, 3), 10)
    : 0;

  validateField("hour",        hour, 0, 23);
  validateField("minute",      min,  0, 59);
  validateField("second",      sec,  0, 60); // 60 allows leap seconds
  validateField("millisecond", ms,   0, 999);

  // Build UTC timestamp, then subtract the offset so the result is UTC
  let utcMs = Date.UTC(year, month - 1, day, hour, min, sec, ms);

  if (rawOffH !== undefined && rawOffM !== undefined) {
    const offH   = parseInt(rawOffH, 10); // already carries sign
    const offM   = parseInt(rawOffM, 10);
    const offMin = offH * 60 + (offH < 0 ? -offM : offM);
    utcMs -= offMin * 60_000;             // convert local → UTC
  }
  // If no offset token is present we treat the time as UTC (same as "Z")

  return new Date(utcMs);
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year, month) {
  const days = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (month === 2 && isLeapYear(year)) return 29;
  return days[month];
}

function validateField(name, value, min, max) {
  if (value < min || value > max) {
    throw new RangeError(
      `parseDate: ${name} ${value} is out of range [${min}, ${max}]`
    );
  }
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { formatDate, parseDate };
