function formatDate(date, options = {}) {
  if (date === null || date === undefined) {
    throw new TypeError("formatDate: expected a Date or number, got " + date);
  }

  const d = date instanceof Date ? date : new Date(date);

  if (isNaN(d.getTime())) {
    throw new RangeError("formatDate: invalid date value");
  }

  const { dateOnly = false, milliseconds = true, offsetMinutes = null } = options;

  // Determine the display offset (in minutes) and the shifted timestamp.
  const offset = offsetMinutes !== null ? Math.trunc(offsetMinutes) : 0;
  const shifted = new Date(d.getTime() + offset * 60_000);

  const year  = shifted.getUTCFullYear();
  const month = shifted.getUTCMonth() + 1;
  const day   = shifted.getUTCDate();

  const datePart = `${PAD(year, 4)}-${PAD(month)}-${PAD(day)}`;

  if (dateOnly) return datePart;

  const hours   = shifted.getUTCHours();
  const minutes = shifted.getUTCMinutes();
  const seconds = shifted.getUTCSeconds();
  const ms      = shifted.getUTCMilliseconds();

  const timePart =
    `${PAD(hours)}:${PAD(minutes)}:${PAD(seconds)}` +
    (milliseconds ? `.${PAD(ms, 3)}` : "");

  const offsetPart =
    offsetMinutes === null
      ? "Z"
      : formatOffset(offset);

  return `${datePart}T${timePart}${offsetPart}`;
}

/** Converts a signed minute offset into ±HH:MM. */
function formatOffset(totalMinutes) {
  const sign    = totalMinutes >= 0 ? "+" : "-";
  const abs     = Math.abs(totalMinutes);
  const hours   = Math.floor(abs / 60);
  const minutes = abs % 60;
  return `${sign}${PAD(hours)}:${PAD(minutes)}`;
}

// ─── parseDate ────────────────────────────────────────────────────────────────

/**
 * Parses an ISO-8601 string into a Date object (always UTC-normalised).
 *
 * Accepted formats
 *   YYYY-MM-DD
 *   YYYY-MM-DDTHH:mm:ss
 *   YYYY-MM-DDTHH:mm:ss.sss
 *   YYYY-MM-DDTHH:mm:ssZ
 *   YYYY-MM-DDTHH:mm:ss.sssZ
 *   YYYY-MM-DDTHH:mm:ss±HH:MM
 *   YYYY-MM-DDTHH:mm:ss.sss±HH:MM
 *
 * @param {string} str - An ISO-8601 date/datetime string.
 * @returns {Date} UTC-normalised Date object.
 * @throws {TypeError}  if `str` is not a string.
 * @throws {RangeError} if `str` does not match a supported ISO-8601 format
 *                      or contains out-of-range field values.
 *
 * @example
 * parseDate("2024-03-15");
 * // → Date { 2024-03-15T00:00:00.000Z }
 *
 * parseDate("2024-03-15T07:30:00.000-05:00");
 * // → Date { 2024-03-15T12:30:00.000Z }
 */
function parseDate(str) {
  if (typeof str !== "string") {
    throw new TypeError(`parseDate: expected a string, got ${typeof str}`);
  }

  const trimmed = str.trim();
  const match   = ISO_DATE_REGEX.exec(trimmed);

  if (!match) {
    throw new RangeError(`parseDate: "${str}" is not a recognised ISO-8601 format`);
  }

  const [, rawYear, rawMonth, rawDay,
         rawHour, rawMin, rawSec, rawMs,
         rawOffH, rawOffM] = match;

  const year  = parseInt(rawYear,  10);
  const month = parseInt(rawMonth, 10);
  const day   = parseInt(rawDay,   10);

  validateField("month",  month,  1, 12);
  validateField("day",    day,    1, 31);

  // Date-only → midnight UTC
  if (rawHour === undefined) {
    const d = new Date(Date.UTC(year, month - 1, day));
    validateDate(d, year, month, day);
    return d;
  }

  const hour = parseInt(rawHour, 10);
  const min  = parseInt(rawMin,  10);
  const sec  = parseInt(rawSec,  10);
  // Pad or truncate ms fragment to exactly 3 digits
  const ms   = rawMs !== undefined
    ? parseInt(rawMs.padEnd(3, "0").slice(0, 3), 10)
    : 0;

  validateField("hour",        hour, 0, 23);
  validateField("minute",      min,  0, 59);
  validateField("second",      sec,  0, 59);
  validateField("millisecond", ms,   0, 999);

  // Offset in minutes (positive = east of UTC)
  let offsetMinutes = 0;
  if (rawOffH !== undefined && rawOffM !== undefined) {
    const sign    = rawOffH.startsWith("-") ? -1 : 1;
    const offH    = parseInt(rawOffH.slice(1), 10);
    const offM    = parseInt(rawOffM, 10);
    validateField("offset hours",   offH, 0, 23);
    validateField("offset minutes", offM, 0, 59);
    offsetMinutes = sign * (offH * 60 + offM);
  }

  // Build UTC timestamp: local time minus offset = UTC
  const utcMs =
    Date.UTC(year, month - 1, day, hour, min, sec, ms) -
    offsetMinutes * 60_000;

  const result = new Date(utcMs);

  if (isNaN(result.getTime())) {
    throw new RangeError(`parseDate: "${str}" produced an invalid date`);
  }

  return result;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function validateField(name, value, min, max) {
  if (value < min || value > max) {
    throw new RangeError(
      `parseDate: ${name} ${value} is out of range [${min}, ${max}]`
    );
  }
}

function validateDate(d, year, month, day) {
  // Catch month-overflow (e.g. Feb 30)
  if (
    d.getUTCFullYear() !== year ||
    d.getUTCMonth()    !== month - 1 ||
    d.getUTCDate()     !== day
  ) {
    throw new RangeError(
      `parseDate: ${PAD(year, 4)}-${PAD(month)}-${PAD(day)} is not a valid calendar date`
    );
  }
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { formatDate, parseDate };
```

