// → Date: 2024-03-15 10:30:00.000 UTC

parseDate("2024-03-15T12:00:00+02:00");
// → Date: 2024-03-15 10:00:00.000 UTC  (offset applied)

parseDate("2024-03-15");
// → Date: 2024-03-15 00:00:00.000 UTC

parseDate("2024-W11-5");
// → Date: 2024-03-15 00:00:00.000 UTC  (Friday, week 11)

parseDate("2024-075");
// → Date: 2024-03-15 00:00:00.000 UTC  (75th day of 2024)

// ── Round-trip ───────────────────────────────────────────────────────────────

