## Usage Examples

```javascript
const { formatDate, parseDate } = require("./dateUtils");

// ── formatDate ────────────────────────────────────────────────────────────────

const d = new Date("2024-03-15T10:30:00.000Z");

formatDate(d);
// → "2024-03-15T10:30:00.000Z"

formatDate(d, { dateOnly: true });
// → "2024-03-15"

formatDate(d, { ms: false });
// → "2024-03-15T10:30:00Z"

formatDate(d, { offsetMinutes: 330 });   // IST (+05:30)
// → "2024-03-15T16:00:00.000+05:30"

formatDate(d, { offsetMinutes: -300 });  // EST (−05:00)
// → "2024-03-15T05:30:00.000-05:00"

formatDate(d, { offsetMinutes: null, ms: false });  // bare local time
// → "2024-03-15T10:30:00"

// ── parseDate ─────────────────────────────────────────────────────────────────

parseDate("2024-03-15");
// → 2024-03-15T00:00:00.000Z

parseDate("2024-03-15T10:30:00Z");
// → 2024-03-15T10:30:00.000Z

parseDate("2024-03-15T16:00:00.000+05:30");
// → 2024-03-15T10:30:00.000Z  (offset correctly removed)

parseDate("2024-03-15T05:30:00.000-05:00");
// → 2024-03-15T10:30:00.000Z

// Round-trip
const str = "2024-03-15T10:30:00.000Z";
formatDate(parseDate(str)) === str;  // → true
```

