// dateUtils.js

/**
 * Format a Date object as an ISO-8601 date string: YYYY-MM-DD
 * @param {Date} date
 * @returns {string}
 */
export function formatDate(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    throw new TypeError("Expected a valid Date object");
  }

  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const day = String(date.getUTCDate()).padStart(2, "0");

  return `${year}-${month}-${day}`;
}

/**
 * Parse an ISO-8601 date string (YYYY-MM-DD) into a Date object in UTC
 * @param {string} str
 * @returns {Date}
 */
export function parseDate(str) {
  if (typeof str !== "string") {
    throw new TypeError("Expected a string");
  }

  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(str);
  if (!match) {
    throw new Error("Invalid ISO-8601 date format, expected YYYY-MM-DD");
  }

  const [, yearStr, monthStr, dayStr] = match;
  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);

  const date = new Date(Date.UTC(year, month - 1, day));

  // Validate to catch invalid dates like 2024-02-30
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    throw new Error("Invalid calendar date");
  }

  return date;
}
