/**
 * A small collection of mathematical utility functions.
 */

/**
 * Clamps a number between a minimum and maximum value.
 *
 * @param {number} value The number to clamp.
 * @param {number} min The lower bound.
 * @param {number} max The upper bound.
 * @returns {number} The clamped number.
 */
export function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

/**
 * Performs linear interpolation between two values.
 *
 * @param {number} start The start value (when t = 0).
 * @param {number} end The end value (when t = 1).
 * @param {number} t The interpolation factor, typically between 0 and 1.
 * @returns {number} The interpolated value.
 */
export function lerp(start, end, t) {
  return start * (1 - t) + end * t;
  // A slightly more performant version:
  // return start + t * (end - start);
}

/**
 * Generates a random integer within a specified range (inclusive).
 *
 * @param {number} min The minimum possible integer value.
 * @param {number} max The maximum possible integer value.
 * @returns {number} A random integer between min and max.
 */
export function randomInt(min, max) {
  // Ensure inputs are integers
  const minInt = Math.ceil(min);
  const maxInt = Math.floor(max);
  // The maximum is inclusive and the minimum is inclusive
  return Math.floor(Math.random() * (maxInt - minInt + 1)) + minInt;
}
