/**
 * @file A utility module for creating URL-friendly slugs from strings.
 * @exports slugify - The main function to convert a string to a slug.
 * @exports stripAccents - A helper function to remove diacritics/accents.
 */

/**
 * Removes diacritics (accents) from a string by decomposing them into base
 * characters and combining marks, then removing the combining marks.
 *
 * For example, 'é' becomes 'e' + '´', and the '´' is removed.
 *
 * @param {string} str The string to process.
 * @returns {string} The string with accents removed.
 *
 * @example
 * stripAccents('Déjà Vu'); // Returns 'Deja Vu'
 * stripAccents('你好'); // Returns '你好' (non-accented characters are unaffected)
 */
export const stripAccents = (str) => {
  if (typeof str !== 'string') {
    return '';
  }
  // NFD (Normalization Form Canonical Decomposition) separates combined characters
  // into the base character and the accent mark.
  // The regex then removes the accent marks, which are in the U+0300 to U+036F range.
  return str.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
};

/**
 * Converts a string into a URL-friendly slug.
 *
 * The process includes:
 * 1. Removing accents.
 * 2. Converting to lowercase.
 * 3. Replacing special characters (like '&') with words.
 * 4. Replacing non-alphanumeric characters with a hyphen.
 * 5. Collapsing multiple hyphens into a single one.
 * 6. Trimming any leading or trailing hyphens.
 *
 * @param {string} str The string to convert into a slug.
 * @returns {string} The resulting URL-friendly slug.
 *
 * @example
 * slugify('Hello World!'); // Returns 'hello-world'
 * slugify('  -- extra spaces & stuff --  '); // Returns 'extra-spaces-and-stuff'
 * slugify('Cœur à Cœur'); // Returns 'coeur-a-coeur'
 * slugify('Ein schöner Tag'); // Returns 'ein-schoener-tag'
 */
export const slugify = (str) => {
  if (typeof str !== 'string') {
    return '';
  }

  const a = stripAccents(str)
    .toLowerCase()
    .trim()
    // Specific character replacements
    .replace(/ß/g, 'ss') // Replace German Eszett
    .replace(/&/g, '-and-') // Replace ampersand with 'and'

    // Replace all non-word characters (anything except letters, numbers, and underscore)
    // and whitespace with a hyphen. We keep the hyphen to avoid replacing it.
    .replace(/[^\w\s-]/g, '')

    // Replace one or more whitespace characters with a single hyphen.
    .replace(/\s+/g, '-')

    // Replace multiple hyphens with a single hyphen.
    .replace(/-+/g, '-');

  // Remove leading and trailing hyphens that might have been created.
  return a.replace(/^-+|-+$/g, '');
};
