 * @fileoverview A utility module for formatting and parsing ISO-8601 dates.
 * ISO-8601 format is `YYYY-MM-DDTHH:mm:ss.sssZ`.
 */

/**
 * Formats a Date object into an ISO-8601 string in UTC.
 *
 * This function uses the built-in `toISOString()` method, which is the
 * standard and most reliable way to get an ISO-8601 string in JavaScript.
 *
 * @param {Date} date The Date object to format.
 * @returns {string} The ISO-8601 formatted string (e.g., "2023-10-27T10:00:00.000Z").
 * @throws {TypeError} If the provided argument is not a valid Date object.
 */
export function formatDate(date) {
  // Check if the input is a valid Date object.
  // An invalid date's time value is NaN.
  if (!(date instanceof Date) || isNaN(date.getTime())) {
    throw new TypeError('Invalid Date object provided to formatDate.');
  }
  return date.toISOString();
}

/**
 * Parses an ISO-8601 string into a Date object.
 *
 * The JavaScript `Date` constructor is specified to correctly parse ISO-8601
 * strings (including the UTC 'Z' designator) since ECMAScript 5.
 *
 * @param {string} str The ISO-8601 formatted string to parse.
 * @returns {Date} The corresponding Date object.
 * @throws {TypeError} If the string cannot be parsed into a valid date.
 */
export function parseDate(str) {
  if (typeof str !== 'string' || str.length === 0) {
      throw new TypeError('Invalid string provided to parseDate.');
  }

  const date = new Date(str);

  // Check if the constructor returned a valid date.
  // If parsing fails, it returns a Date object whose time value is NaN.
  if (isNaN(date.getTime())) {
    throw new TypeError(`Invalid ISO-8601 date string provided: "${str}"`);
  }

  return date;
}
```

